    46	  terminationDate: 'termination_date',
    47	  employmentStatus: 'employment_status',
    48	};
    49	
    50	export class PgEmployeeRepository implements IEmployeeRepository {
    51	  async findById(id: string): Promise<Employee | null> {
    52	    const result = await pool.query<EmployeeRow>(
    53	      'SELECT * FROM employees WHERE id = $1 AND deleted_at IS NULL',
    54	      [id],
    55	    );
    56	    if (result.rows.length === 0) {
    57	      return null;
    58	    }
    59	    return mapRowToEmployee(result.rows[0]);
    60	  }
    61	
    62	  async findByEmployeeNumber(employeeNumber: string): Promise<Employee | null> {
    63	    const result = await pool.query<EmployeeRow>(
    64	      'SELECT * FROM employees WHERE employee_number = $1 AND deleted_at IS NULL',
    65	      [employeeNumber],
    66	    );
    67	    if (result.rows.length === 0) {
    68	      return null;
    69	    }
    70	    return mapRowToEmployee(result.rows[0]);
    71	  }
    72	
    73	  async findAll(): Promise<Employee[]> {
    74	    const result = await pool.query<EmployeeRow>(
    75	      'SELECT * FROM employees WHERE deleted_at IS NULL',
    76	    );
    77	    return result.rows.map(mapRowToEmployee);
    78	  }
    79	
    80	  async create(
    81	    employee: Omit<Employee, 'id' | 'createdAt' | 'updatedAt' | 'deletedAt'>,
    82	  ): Promise<Employee> {
    83	    const result = await pool.query<EmployeeRow>(
    84	      `INSERT INTO employees (
    85	        employee_number, first_name, last_name, email,
    86	        manager_id, department, hire_date, termination_date, employment_status
    87	      ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
    88	      RETURNING *`,
    89	      [
    90	        employee.employeeNumber,
    91	        employee.firstName,
    92	        employee.lastName,
    93	        employee.email,
    94	        employee.managerId,
    95	        employee.department,
    96	        employee.hireDate,
    97	        employee.terminationDate,
    98	        employee.employmentStatus,
    99	      ],
   100	    );
   101	    return mapRowToEmployee(result.rows[0]);
   102	  }
